#include <vector>
#include <unordered_map>

class Solution {
public:
    long long countGood(std::vector<int>& nums, int k) {
        std::unordered_map<int, int> count;
        long long ans = 0;
        int left = 0;
        long long curPairs = 0;
        int n = nums.size();
        for (int right = 0; right < n; ++right) {
            curPairs += count[nums[right]]++;
            while (curPairs >= k) {
                ans += (n - right);
                curPairs -= --count[nums[left]];
                left++;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long countGood(int[] nums, int k) {
        Map<Integer, Integer> count = new HashMap<>();
        long ans = 0;
        int left = 0;
        long curPairs = 0;
        int n = nums.length;
        for (int right = 0; right < n; right++) {
            int c = count.getOrDefault(nums[right], 0);
            curPairs += c;
            count.put(nums[right], c + 1);
            while (curPairs >= k) {
                ans += (n - right);
                int lc = count.get(nums[left]);
                curPairs -= (lc - 1);
                count.put(nums[left], lc - 1);
                left++;
            }
        }
        return ans;
    }
}

